INSERT INTO "email_templates" ("id","org_id","name","category","subject","preview_text","body","status","owner_id","deleted_at","created_at","updated_at","html","css","plain_text","builder","thumbnail") VALUES('0171587e-5745-47bf-a209-046eceae2729','b592317e-3415-42f5-ad19-4820eeacd4ab','Subscription renewal','Transactional','Your {{plan_name}} plan renews on {{renewal_date}}','Nothing to do — here is what changes.',replace('<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GoFox</title></head>\n<body style="margin:0;padding:0;background:#F4F6F9;">\n<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F4F6F9;padding:28px 12px;"><tr><td align="center">\n<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;background:#ffffff;border-radius:14px;overflow:hidden;box-shadow:0 1px 3px rgba(16,24,40,.08)">\n\n<tr><td style="padding:30px 36px 0">\n  <div style="font-family:Arial;font-size:11px;font-weight:700;letter-spacing:1.6px;color:#159C91">BILLING</div>\n  <h1 style="margin:0 0 14px;font-family:Arial,Helvetica,sans-serif;font-size:24px;line-height:1.25;color:#0F2E2B;letter-spacing:-.4px">Your plan renews in 7 days</h1>\n  <p style="margin:0 0 16px;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.65;color:#475467">Hi {{first_name}}, your <strong style="color:#0F2E2B">{{plan_name}}</strong> subscription renews on <strong style="color:#0F2E2B">{{renewal_date}}</strong>. No action needed.</p>\n</td></tr>\n<tr><td style="padding:0 36px">\n  <table role="presentation" width="100%" style="background:#F7F8FA;border-radius:12px;padding:20px">\n    <tr><td style="font-family:Arial;font-size:12.5px;color:#667085">Amount</td><td align="right" style="font-family:Arial;font-size:13px;font-weight:700;color:#0F2E2B">{{renewal_amount}} / {{billing_period}}</td></tr>\n    <tr><td style="font-family:Arial;font-size:12.5px;color:#667085;padding-top:10px">Payment method</td><td align="right" style="font-family:Arial;font-size:13px;color:#0F2E2B;padding-top:10px">{{payment_method}}</td></tr>\n  </table>\n</td></tr>\n<tr><td style="padding:22px 36px 34px">\n  <table role="presentation"><tr>\n    <td style="padding-right:14px"><table role="presentation" cellpadding="0" cellspacing="0" style="margin:0"><tr><td style="border-radius:8px;background:#159C91"><a href="{{billing_url}}" style="display:inline-block;padding:13px 26px;font-family:Arial,Helvetica,sans-serif;font-size:14px;font-weight:700;color:#ffffff;text-decoration:none;letter-spacing:.2px">Manage billing</a></td></tr></table></td>\n    <td><a href="{{cancel_url}}" style="font-family:Arial;font-size:12px;color:#98A2B3">Cancel plan</a></td>\n  </tr></table>\n</td></tr>\n</table>\n<p style="margin:16px 0 0;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#98A2B3;text-align:center">Sent with GoFox CRM · <a href="{{unsubscribe_url}}" style="color:#98A2B3">Unsubscribe</a></p>\n</td></tr></table></body></html>','\n',char(10)),'active',NULL,NULL,'2026-11-18T18:32:22.991Z','2026-11-18T18:32:22.991Z',replace('<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GoFox</title></head>\n<body style="margin:0;padding:0;background:#F4F6F9;">\n<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F4F6F9;padding:28px 12px;"><tr><td align="center">\n<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;background:#ffffff;border-radius:14px;overflow:hidden;box-shadow:0 1px 3px rgba(16,24,40,.08)">\n\n<tr><td style="padding:30px 36px 0">\n  <div style="font-family:Arial;font-size:11px;font-weight:700;letter-spacing:1.6px;color:#159C91">BILLING</div>\n  <h1 style="margin:0 0 14px;font-family:Arial,Helvetica,sans-serif;font-size:24px;line-height:1.25;color:#0F2E2B;letter-spa