INSERT INTO "email_templates" ("id","org_id","name","category","subject","preview_text","body","status","owner_id","deleted_at","created_at","updated_at","html","css","plain_text","builder","thumbnail") VALUES('463304d4-a9f7-4695-91e7-dfeb3737031f','b592317e-3415-42f5-ad19-4820eeacd4ab','Sales follow-up','Sales','Following up on {{deal_name}}','A short recap and one clear next step.',replace('<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GoFox</title></head>\n<body style="margin:0;padding:0;background:#F4F6F9;">\n<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F4F6F9;padding:28px 12px;"><tr><td align="center">\n<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;background:#ffffff;border-radius:14px;overflow:hidden;box-shadow:0 1px 3px rgba(16,24,40,.08)">\n\n<tr><td style="padding:34px 38px 0">\n  <p style="margin:0 0 16px;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.65;color:#101828">Hi {{first_name}},</p>\n  <p style="margin:0 0 16px;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.65;color:#475467">Thanks for the conversation about <strong style="color:#101828">{{deal_name}}</strong>. Quick recap so nothing gets lost:</p>\n  <table role="presentation" width="100%" style="margin:0 0 18px">\n    <tr><td style="padding:8px 0 8px 14px;border-left:2px solid #FF7417;font-family:Arial;font-size:13.5px;color:#475467;line-height:1.6">You wanted a rollout that does not disrupt the team in {{company_name}}.</td></tr>\n  </table>\n  <p style="margin:0 0 16px;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.65;color:#475467">I have put together a two-week pilot plan. It needs about 20 minutes of your time on day one — the rest runs itself.</p>\n  <p style="margin:0 0 16px;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.65;color:#475467">Is {{suggested_time}} still workable for a short call?</p>\n</td></tr>\n<tr><td style="padding:0 38px 34px">\n  <table role="presentation" cellpadding="0" cellspacing="0" style="margin:0"><tr><td style="border-radius:8px;background:#17243A"><a href="{{booking_url}}" style="display:inline-block;padding:13px 26px;font-family:Arial,Helvetica,sans-serif;font-size:14px;font-weight:700;color:#ffffff;text-decoration:none;letter-spacing:.2px">Book the pilot call</a></td></tr></table>\n  <div style="margin-top:26px;padding-top:18px;border-top:1px solid #E7EAF0;font-family:Arial;font-size:13px;line-height:1.6;color:#475467"><strong style="color:#101828">{{owner_name}}</strong><br>{{owner_title}} · GoFox<br><a href="mailto:{{owner_email}}" style="color:#FF7417;text-decoration:none">{{owner_email}}</a></div>\n</td></tr>\n</table>\n<p style="margin:16px 0 0;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#98A2B3;text-align:center">Sent with GoFox CRM · <a href="{{unsubscribe_url}}" style="color:#98A2B3">Unsubscribe</a></p>\n</td></tr></table></body></html>','\n',char(10)),'active',NULL,NULL,'2026-11-18T19:03:01.326Z','2026-11-18T19:03:01.326Z',replace('<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GoFox</title></head>\n<body style="margin:0;padding:0;background:#F4F6F9;">\n<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F4F6F9;padding:28px 12px;"><tr><td align="center">\n<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;background:#ffffff;border-radius:14px;overflow:hidden;box-shadow:0 1px 3px rgba(16,24,40,.08)">\n\n<tr><td style="padding:34px 38px 0">\n  <p style="margin:0 0 16px;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.65;color:#101828">Hi {{first_name}},</p>\n  <p style="margin:0 0 16px;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.65;color:#475467">Thanks for the conversation about <strong style="color:#101828">{{deal_name}}</strong>. Quick recap so nothing gets lost:</p>\n  <table role="presentation" width="100%" style="margin:0 0 18px">\n    <tr><td style="padding:8px 0 8px 14px;border-left:2px solid #FF7417;font-family:Arial;font-size:13.5px;color:#475467;line-height:1.6">You wanted a rollout that does not disrupt the team in {{company_name}}.</td></tr>\n  </table>\n  <p style="margin:0 0 16px;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.65;color:#475467">I have put together a two-week pilot plan. It needs about 20 minutes of your time on day one — the rest runs itself.</p>\n  <p style="margin:0 0 16px;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.65;color:#475467">Is {{suggested_time}} still workable for a short call?</p>\n</td></tr>\n<tr><td style="padding:0 38px 34px">\n  <table role="presentation" cellpadding="0" cellspacing="0" style="margin:0"><tr><td style="border-radius:8px;background:#17243A"><a href="{{booking_url}}" style="display:inline-block;padding:13px 26px;font-family:Arial,Helvetica,sans-serif;font-size:14px;font-weight:700;color:#ffffff;text-decoration:none;letter-spacing:.2px">Book the pilot call</a></td></tr></table>\n  <div style="margin-top:26px;padding-top:18px;border-top:1px solid #E7EAF0;font-family:Arial;font-size:13px;line-height:1.6;color:#475467"><strong style="color:#101828">{{owner_name}}</strong><br>{{owner_title}} · GoFox<br><a href="mailto:{{owner_email}}" style="color:#FF7417;text-decoration:none">{{owner_email}}</a></div>\n</td></tr>\n</table>\n<p style="margin:16px 0 0;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#98A2B3;text-align:center">Sent with GoFox CRM · <a href="{{unsubscribe_url}}" style="color:#98A2B3">Unsubscribe</a></p>\n</td></tr></table></body></html>','\n',char(10)),NULL,replace('Hi {{first_name}},\n\nThanks for the conversation about {{deal_name}}.\n\nYou wanted a rollout that does not disrupt {{company_name}}. I have a two-week pilot plan ready.\n\nIs {{suggested_time}} still workable?\n\n{{owner_name}}\n{{owner_title}} · GoFox','\n',char(10)),'design',NULL);
INSERT INTO "email_templates" ("id","org_id","name","category","subject","preview_text","body","status","owner_id","deleted_at","created_at","updated_at","html","css","plain_text","builder","thumbnail") VALUES('ef5d5e95-f8a9-485e-8bcc-df5edacedfff','b592317e-3415-42f5-ad19-4820eeacd4ab','Subscription renewal','Transactional','Your {{plan_name}} plan renews on {{renewal_date}}','Nothing to do — here is what changes.',replace('<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GoFox</title></head>\n<body style="margin:0;padding:0;background:#F4F6F9;">\n<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F4F6F9;padding:28px 12px;"><tr><td align="center">\n<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;background:#ffffff;border-radius:14px;overflow:hidden;box-shadow:0 1px 3px rgba(16,24,40,.08)">\n\n<tr><td style="padding:30px 36px 0">\n  <div style="font-family:Arial;font-size:11px;font-weight:700;letter-spacing:1.6px;color:#159C91">BILLING</div>\n  <h1 style="margin:0 0 14px;font-family:Arial,Helvetica,sans-serif;font-size:24px;line-height:1.25;color:#0F2E2B;letter-spacing:-.4px">Your plan renews in 7 days</h1>\n  <p style="margin:0 0 16px;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.65;color:#475467">Hi {{first_name}}, your <strong style="color:#0F2E2B">{{plan_name}}</strong> subscription renews on <strong style="color:#0F2E2B">{{renewal_date}}</strong>. No action needed.</p>\n</td></tr>\n<tr><td style="padding:0 36px">\n  <table role="presentation" width="100%" style="background:#F7F8FA;border-radius:12px;padding:20px">\n    <tr><td style="font-family:Arial;font-size:12.5px;color:#667085">Amount</td><td align="right" style="font-family:Arial;font-size:13px;font-weight:700;color:#0F2E2B">{{renewal_amount}} / {{billing_period}}</td></tr>\n    <tr><td style="font-family:Arial;font-size:12.5px;color:#667085;padding-top:10px">Payment method</td><td align="right" style="font-family:Arial;font-size:13px;color:#0F2E2B;padding-top:10px">{{payment_method}}</td></tr>\n  </table>\n</td></tr>\n<tr><td style="padding:22px 36px 34px">\n  <table role="presentation"><tr>\n    <td style="padding-right:14px"><table role="presentation" cellpadding="0" cellspacing="0" style="margin:0"><tr><td style="border-radius:8px;background:#159C91"><a href="{{billing_url}}" style="display:inline-block;padding:13px 26px;font-family:Arial,Helvetica,sans-serif;font-size:14px;font-weight:700;color:#ffffff;text-decoration:none;letter-spacing:.2px">Manage billing</a></td></tr></table></td>\n    <td><a href="{{cancel_url}}" style="font-family:Arial;font-size:12px;color:#98A2B3">Cancel plan</a></td>\n  </tr></table>\n</td></tr>\n</table>\n<p style="margin:16px 0 0;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#98A2B3;text-align:center">Sent with GoFox CRM · <a href="{{unsubscribe_url}}" style="color:#98A2B3">Unsubscribe</a></p>\n</td></tr></table></body></html>','\n',char(10)),'active',NULL,NULL,'2026-11-18T19:03:01.377Z','2026-11-18T19:03:01.377Z',replace('<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GoFox</title></head>\n<body style="margin:0;padding:0;background:#F4F6F9;">\n<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F4F6F9;padding:28px 12px;"><tr><td align="center">\n<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;background:#ffffff;border-radius:14px;overflow:hidden;box-shadow:0 1px 3px rgba(16,24,40,.08)">\n\n<tr><td style="padding:30px 36px 0">\n  <div style="font-family:Arial;font-size:11px;font-weight:700;letter-spacing:1.6px;color:#159C91">BILLING</div>\n  <h1 style="margin:0 0 14px;font-family:Arial,Helvetica,sans-serif;font-size:24px;line-height:1.25;color:#0F2E2B;letter-spa