anage billing: {{billing_url}}','\n',char(10)),'design',NULL);
INSERT INTO "email_templates" ("id","org_id","name","category","subject","preview_text","body","status","owner_id","deleted_at","created_at","updated_at","html","css","plain_text","builder","thumbnail") VALUES('1ce49bd3-d863-4801-8a59-f1e00438b909','b592317e-3415-42f5-ad19-4820eeacd4ab','Abandoned cart','E-Commerce','Still thinking it over, {{first_name}}?','Your cart is saved — and stock is low.',replace('<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GoFox</title></head>\n<body style="margin:0;padding:0;background:#F4F6F9;">\n<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F4F6F9;padding:28px 12px;"><tr><td align="center">\n<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;background:#ffffff;border-radius:14px;overflow:hidden;box-shadow:0 1px 3px rgba(16,24,40,.08)">\n\n<tr><td style="padding:30px 34px 0">\n  <h1 style="margin:0 0 14px;font-family:Arial,Helvetica,sans-serif;font-size:25px;line-height:1.25;color:#17243A;letter-spacing:-.4px">Your cart is still here</h1>\n  <p style="margin:0 0 16px;font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.65;color:#5B6577">We saved the items you picked. Nothing is reserved, so if something catches your eye it is worth finishing now.</p>\n</td></tr>\n<tr><td style="padding:0 34px">\n  <table role="presentation" width="100%" style="border:1px solid #E7EAF0;border-radius:12px;padding:16px">\n    <tr><td width="64"><div style="width:56px;height:56px;border-radius:8px;background:#FFF3E8;text-align:center;line-height:56px;font-size:24px">🛍️</div></td>\n    <td style="font-family:Arial"><div style="font-size:13.5px;font-weight:700;color:#17243A">{{product_name}}</div><div style="font-size:12px;color:#667085;margin-top:2px">{{product_variant}} · Qty {{quantity}}</div><div style="font-size:13.5px;font-weight:700;color:#17243A;margin-top:6px">{