INSERT INTO "ai_messages" ("id","org_id","user_id","role","body","sources","created_at") VALUES('362b62c8-afec-4973-ab24-4a425e66e472','7e5b2df4-859d-4d89-9186-92754d0334af','4d52aa5e-9e25-4d3d-a7a6-80b89bed2190','assistant',replace('This workspace has 5 contacts. Ask me about a specific contact by name and I will pull the record.\n\n(Rules-based mode: no AI provider is connected. Answers are computed from your CRM data with server-side queries; nothing is generated externally. Connect a provider in Settings → Apps to use a model.)','\n',char(10)),'[{"label":"Browse contacts","href":"/contacts"}]','2026-11-18T12:40:26.458Z');
INSERT INTO "ai_messages" ("id","org_id","user_id","role","body","sources","created_at") VALUES('db05896e-4c46-4360-b584-dfd9867adb1d','e6402428-4421-496d-a830-8fdb68a3547f','90d88eed-ca34-4d0f-9922-f795326f2015','user','hi how are you',NULL,'2026-11-19T04:56:51.958Z');
INSERT INTO "ai_messages" ("id","org_id","user_id","role","body","sources","created_at") VALUES('c7f6de61-2f18-4bdc-aed4-84beb6a200b4','e6402428-4421-496d-a830-8fdb68a3547f','90d88eed-ca34-4d0f-9922-f795326f2015','assistant',replace('I can answer questions about your pipeline, contacts, tasks and automations. Ask something like "how is the pipeline looking?" or "what are my tasks this week?".\n\n(Rules-based mode: no AI provider is connected. Answers are computed from your CRM data with server-side queries; nothing is generated externally. Connect a provider in Settings → Apps to use a model.)','\n',char(10)),'[{"label":"Home dashboard","href":"/"}]','2026-11-19T04:56:51.966Z');
